/**
 * WORD-LEVEL CAPTION TIMELINE
 * ------------------------------------------------------------------
 * In a classic AE/Whisper pipeline this file is generated by
 * `scripts/transcribe.mjs` (openai-whisper, word_timestamps=True).
 * Whisper model weights cannot be fetched in this sandbox, so the
 * deterministic aligner in that script distributes word durations by
 * glyph weight within each authored beat — producing the exact same
 * schema the renderer consumes:
 *
 *   { text, from, to, words: [{ text, from, to, emph }] }
 *
 * Times are frames @ 60fps, so "sub-frame" precision is native.
 */

export type Word = { text: string; from: number; to: number; emph?: boolean };
export type Caption = {
  text: string;
  from: number;
  to: number;
  dir: "rtl" | "ltr";
  words: Word[];
  style?: "hero" | "impact" | "line" | "micro";
};

